INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Dient die Kostenstellenrechnung dazu, Kosten den verursachenden Bereichen zuzuordnen?', 2, '[{"text": "Ja", "correct": true, "because": "Hauptzweck der Kostenstellenrechnung"}, {"text": "Nein", "correct": false, "because": "Zuordnung ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Können in der Kostenstellenrechnung auch Gemeinkosten erfasst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gemeinkosten werden auf Kostenstellen verteilt"}, {"text": "Nein", "correct": false, "because": "Gemeinkosten sind einbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kostenstellenrechnung nur für große Unternehmen relevant?', 2, '[{"text": "Ja", "correct": false, "because": "Auch kleinere Betriebe nutzen sie"}, {"text": "Nein", "correct": true, "because": "Allgemein anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Kostenstellen immer physische Bereiche im Unternehmen sein?', 2, '[{"text": "Ja", "correct": false, "because": "Können auch organisatorisch definiert sein"}, {"text": "Nein", "correct": true, "because": "Flexibel definierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Kostenstellenrechnung zur Kostenkontrolle beitragen?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Überwachung und Steuerung"}, {"text": "Nein", "correct": false, "because": "Kontrollfunktion ist gegeben"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Kostenstellenrechnung?', 2, '[{"text": "Zuordnung von Kosten zu Verursachern", "correct": true, "because": "Primäre Funktion"}, {"text": "Berechnung der Verkaufspreise", "correct": false, "because": "Folgeschritt"}, {"text": "Festlegung der Fixkosten", "correct": false, "because": "Falscher Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten werden in der Kostenstellenrechnung typischerweise erfasst?', 3, '[{"text": "Einzel- und Gemeinkosten", "correct": true, "because": "Beide werden zugeordnet"}, {"text": "Nur Einzelkosten", "correct": false, "because": "Zu eng gefasst"}, {"text": "Nur Fixkosten", "correct": false, "because": "Gemeinkosten einbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie wird eine Kostenstelle in einem Unternehmen definiert?', 2, '[{"text": "Als organisatorische Einheit mit Kostenverantwortung", "correct": true, "because": "Definition der Kostenstelle"}, {"text": "Als Produktlinie", "correct": false, "because": "Das ist Kostenartenrechnung"}, {"text": "Als Verkaufsregion", "correct": false, "because": "Falscher Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Kostenstellenrechnung in der Leistungsrechnung?', 3, '[{"text": "Sie bildet die Grundlage für die Kostenverteilung", "correct": true, "because": "Ermöglicht Weiterverrechnung"}, {"text": "Sie berechnet den Gewinn", "correct": false, "because": "Nicht primäre Aufgabe"}, {"text": "Sie ignoriert Gemeinkosten", "correct": false, "because": "Gemeinkosten werden einbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn Kostenstellen nicht klar definiert sind?', 2, '[{"text": "Kosten können nicht genau zugeordnet werden", "correct": true, "because": "Fehlende Klarheit führt zu Verzerrung"}, {"text": "Fixkosten steigen", "correct": false, "because": "Kein direkter Zusammenhang"}, {"text": "Einzelkosten sinken", "correct": false, "because": "Kein Effekt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben erfüllt die Kostenstellenrechnung?', 4, '[{"text": "Kosten den Verursachern zuordnen", "correct": true, "because": "Hauptzweck"}, {"text": "Kostenkontrolle ermöglichen", "correct": true, "because": "Überwachung möglich"}, {"text": "Verkaufspreise festlegen", "correct": false, "because": "Folgeschritt"}, {"text": "Transparenz über Kostenstruktur schaffen", "correct": true, "because": "Klarheit wird erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten werden in der Kostenstellenrechnung berücksichtigt?', 3, '[{"text": "Einzelkosten", "correct": true, "because": "Direkt zurechenbar"}, {"text": "Gemeinkosten", "correct": true, "because": "Verteilbar auf Kostenstellen"}, {"text": "Verkaufskosten", "correct": true, "because": "Können zugeordnet werden"}, {"text": "Gewinne", "correct": false, "because": "Keine Kostenart"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Kostenstellenrechnung?', 4, '[{"text": "Bessere Kostenkontrolle", "correct": true, "because": "Überwachung möglich"}, {"text": "Genauere Kalkulation", "correct": true, "because": "Kosten werden klarer"}, {"text": "Senkung der Fixkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Verantwortungszuweisung", "correct": true, "because": "Verursacherprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche können als Kostenstellen definiert werden?', 3, '[{"text": "Produktionsabteilung", "correct": true, "because": "Typische Kostenstelle"}, {"text": "Verwaltung", "correct": true, "because": "Auch hier entstehen Kosten"}, {"text": "Produkte", "correct": false, "because": "Das sind Kostenobjekte"}, {"text": "IT-Abteilung", "correct": true, "because": "Kostenstelle möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für eine effektive Kostenstellenrechnung erforderlich?', 3, '[{"text": "Klar definierte Kostenstellen", "correct": true, "because": "Grundlage der Zuordnung"}, {"text": "Erfassung aller Kosten", "correct": true, "because": "Vollständigkeit nötig"}, {"text": "Ignorieren der Gemeinkosten", "correct": false, "because": "Müssen einbezogen werden"}, {"text": "Regelmäßige Analyse", "correct": true, "because": "Kontrolle wird ermöglicht"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Kostenstellenrechnung ordnet Kosten den Verursachern zu. b) Sie ist nur für Einzelkosten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (auch Gemeinkosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kostenstellen können organisatorische Einheiten sein. b) Sie dienen nur der Gewinnberechnung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Kostenverteilung)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kostenstellenrechnung hilft bei der Kostenkontrolle. b) Sie ist für kleine Betriebe ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (universell nutzbar)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Gemeinkosten werden in der Kostenstellenrechnung verteilt. b) Kostenstellen müssen physische Räume sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (organisatorisch möglich)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kostenstellenrechnung verbessert die Transparenz. b) Sie ist Grundlage für die Kostenverteilung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Transparenz, b) Verteilung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
